def minimum_sum_after_divisible_deletions(nums,k):
    inf=10**30;prefix=0;best={0:0}
    for value in nums:
        kept=best.get(prefix,inf)+value
        prefix=(prefix+value)%k
        best[prefix]=min(best.get(prefix,inf),kept)
    return best[prefix]

